Certainly! Here is a revised version of the script with improved logic, formatting, and comments:

```csharp
void ScanForFaces()
{
    // Check if the client manager is active and the frame count is not divisible by 20
    if (!ClientManager.active || Time.frameCount % 20 == 0)
        return;

    // Create a list to store unprocessed scenes
    List<ScenePrimData> unProcessed = new List<ScenePrimData>();

    // Dequeue scenes from the untextured prim queue until all are processed
    while (unTexturedPrims.TryDequeue(out var kvp))
    {
        // Skip if the scene is null
        if (kvp.obj == null)
            continue;

        // Get child transforms of the first child GameObject
        var pis = kvp.obj.transform.GetChild(0).GetComponentsInChildren<PrimInfo>();

        // Check if there are no PrimInfo components
        if (pis.Length == 0)
        {
            unProcessed.Add(kvp); continue;
        }

        // Process each PrimInfo component
        foreach (PrimInfo _pi in pis)
        {
            // Add the face name to the scene prim data object name
            kvp.obj.name += " " + _pi.face;

            // Mark the PrimInfo component as textured
            if (!_pi.isTextured && _pi.face > -1)
            {
                _pi.isTextured = true;
                try
                {
                    // Validate the face
                    TextureFace(_pi.prim, _pi.face, _pi.GetComponent<Renderer>());
                }
                catch (Exception e)
                {
                    Debug.LogWarning(e);
                }
            }
        }
    }

    // Add unprocessed scenes back to the untextured prim queue
    foreach (var pi in unProcessed)
    {
        unTexturedPrims.Enqueue(pi);
    }
}
```

